// TestNilParams checks a nil params argument fails before any call.
func TestNilParams(t *testing.T) {
	f, addr := startFake(t)
	c := newClient(t, addr)
	_, err := c.Availability.ComputeAvailability(context.Background(), nil)
	if !errors.Is(err, freebusy.ErrInvalidArgument) {
		t.Fatalf("err = %v, want ErrInvalidArgument", err)
	}
	if f.count() != 0 {
		t.Error("a call was made")
	}
}

// TestRequiredField checks a REQUIRED field left empty fails before any
// call, naming the field.
func TestRequiredField(t *testing.T) {
	f, addr := startFake(t)
	c := newClient(t, addr)
	_, err := c.Availability.ComputeAvailability(context.Background(), &allocationpb.ComputeAvailabilityRequest{})
	e, ok := freebusy.AsError(err)
	if !ok || !errors.Is(err, freebusy.ErrInvalidArgument) {
		t.Fatalf("err = %v, want an *Error with InvalidArgument", err)
	}
	if len(e.Violations) != 1 || e.Violations[0].Field != "window" {
		t.Errorf("violations = %v, want %s", e.Violations, "window")
	}
	if f.count() != 0 {
		t.Error("a call was made")
	}
}

// TestErrors checks a failed call becomes an *Error carrying the status's
// ErrorInfo and BadRequest, matched by the sentinels.
func TestErrors(t *testing.T) {
	f, addr := startFake(t)
	c := newClient(t, addr)
	f.respond = func(string, proto.Message, int) (proto.Message, error) {
		s, _ := status.New(codes.FailedPrecondition, "no").WithDetails(
			&errdetails.ErrorInfo{Reason: "CAPACITY_EXHAUSTED", Domain: "freebusy.dev", Metadata: map[string]string{"k": "v"}},
			&errdetails.BadRequest{FieldViolations: []*errdetails.BadRequest_FieldViolation{{Field: "a.b", Description: "bad"}}},
		)
		return nil, s.Err()
	}
	_, err := c.Availability.ComputeAvailability(context.Background(), filled(&allocationpb.ComputeAvailabilityRequest{}, "window"))
	e, ok := freebusy.AsError(err)
	if !ok {
		t.Fatalf("err = %T %v, want *Error", err, err)
	}
	if e.Code != codes.FailedPrecondition || e.Reason != "CAPACITY_EXHAUSTED" || e.Metadata["k"] != "v" || e.Message != "no" {
		t.Errorf("error = %+v", e)
	}
	if len(e.Violations) != 1 || e.Violations[0].Field != "a.b" {
		t.Errorf("violations = %+v", e.Violations)
	}
	if !errors.Is(err, freebusy.ErrFailedPrecondition) {
		t.Error("errors.Is(err, ErrFailedPrecondition) = false")
	}
	if !errors.Is(err, freebusy.ErrCapacityExhausted) {
		t.Error("errors.Is(err, ErrCapacityExhausted) = false")
	}
	if errors.Is(err, freebusy.ErrNotFound) {
		t.Error("errors.Is(err, ErrNotFound) = true")
	}
	if status.Code(err) != codes.FailedPrecondition {
		t.Errorf("status.Code(err) = %v", status.Code(err))
	}
}

// TestMetadata checks client-wide, per-service and per-call metadata reach the server.
func TestMetadata(t *testing.T) {
	f, addr := startFake(t)
	c := newClient(t, addr, option.WithMetadata("x-client", "a"))
	svc := c.Availability.WithOptions(option.WithMetadata("x-service", "b"))
	if _, err := svc.ComputeAvailability(context.Background(), filled(&allocationpb.ComputeAvailabilityRequest{}, "window"), option.WithMetadata("x-call", "c")); err != nil {
		t.Fatal(err)
	}
	md := f.last(t).md
	for k, want := range map[string]string{"x-client": "a", "x-service": "b", "x-call": "c"} {
		if got := md.Get(k); len(got) != 1 || got[0] != want {
			t.Errorf("metadata %s = %v, want %s", k, got, want)
		}
	}
}

