// TestTimeout checks option.WithTimeout bounds a call.
func TestTimeout(t *testing.T) {
	f, addr := startFake(t)
	c := newClient(t, addr)
	f.respond = func(string, proto.Message, int) (proto.Message, error) {
		time.Sleep(300 * time.Millisecond)
		return nil, nil
	}
	_, err := c.Availability.ComputeAvailability(context.Background(), filled(&allocationpb.ComputeAvailabilityRequest{}, "window"), option.WithTimeout(50*time.Millisecond))
	if !errors.Is(err, freebusy.ErrDeadlineExceeded) {
		t.Fatalf("err = %v, want ErrDeadlineExceeded", err)
	}
}

// TestRetries checks a call failing with UNAVAILABLE is retried.
func TestRetries(t *testing.T) {
	f, addr := startFake(t)
	c := newClient(t, addr)
	f.respond = func(_ string, _ proto.Message, n int) (proto.Message, error) {
		if n == 1 {
			return nil, status.Error(codes.Unavailable, "try again")
		}
		return nil, nil
	}
	if _, err := c.Availability.ComputeAvailability(context.Background(), filled(&allocationpb.ComputeAvailabilityRequest{}, "window"), option.WithMaxRetries(2)); err != nil {
		t.Fatal(err)
	}
	if n := f.count(); n != 2 {
		t.Errorf("server saw %d calls, want 2", n)
	}
}

// TestPagination checks one page with SearchAvailability and every item with
// SearchAvailabilityAutoPaging, across two pages.
func TestPagination(t *testing.T) {
	f, addr := startFake(t)
	c := newClient(t, addr)
	f.respond = func(method string, req proto.Message, _ int) (proto.Message, error) {
		out := methods[method].out()
		r := out.ProtoReflect()
		items := r.Mutable(r.Descriptor().Fields().ByName("matches")).List()
		token := req.ProtoReflect().Get(req.ProtoReflect().Descriptor().Fields().ByName("page_token")).String()
		n := 1
		if token == "" {
			n = 2
			r.Set(r.Descriptor().Fields().ByName("next_page_token"), protoreflect.ValueOfString("page-2"))
		}
		for i := 0; i < n; i++ {
			items.Append(items.NewElement())
		}
		return out, nil
	}
	page, err := c.Availability.SearchAvailability(context.Background(), filled(&allocationpb.SearchAvailabilityRequest{}, "window"))
	if err != nil {
		t.Fatal(err)
	}
	if got := page.GetNextPageToken(); got != "page-2" {
		t.Errorf("next page token = %q", got)
	}
	pager := c.Availability.SearchAvailabilityAutoPaging(context.Background(), filled(&allocationpb.SearchAvailabilityRequest{}, "window"))
	n := 0
	for _, err := range pager.All() {
		if err != nil {
			t.Fatal(err)
		}
		n++
	}
	if n != 3 {
		t.Errorf("AutoPaging yielded %d items, want 3", n)
	}
}

// TestWithService checks option.WithService gives one service a connection
// of its own while the others keep the client's.
func TestWithService(t *testing.T) {
	main, addr := startFake(t)
	other, otherAddr := startFake(t)
	c := newClient(t, addr, option.WithService("holds", option.WithEndpoint(otherAddr)))
	_, err := c.Holds.New(context.Background(), filled(&allocationpb.CreateHoldRequest{}, "hold"))
	if err != nil {
		t.Fatal(err)
	}
	if other.count() != 1 || main.count() != 0 {
		t.Fatalf("calls: overridden service's server %d, client's %d; want 1, 0", other.count(), main.count())
	}
	if _, err := c.Availability.ComputeAvailability(context.Background(), filled(&allocationpb.ComputeAvailabilityRequest{}, "window")); err != nil {
		t.Fatal(err)
	}
	if main.count() != 1 {
		t.Errorf("the other services did not keep the client's connection")
	}
}
